'use server'

import { redirect } from 'next/navigation'
import { withAuth } from '@/lib/with-auth'

import { z } from 'zod'
import { prisma } from '@/lib/prisma'
import { revalidatePath } from 'next/cache'
import { recordAuditLog } from '@/lib/audit-logger'
import { headers } from 'next/headers'
import crypto from 'crypto'
import { Resend } from 'resend'
import { WelcomeEmail } from '@/components/emails/WelcomeEmail'
import { render } from '@react-email/render'
import React from 'react'
import { format, parseISO, isValid, addDays } from 'date-fns'
import { Prisma, PaymentStatus, SubscriptionStatus } from '@prisma/client'
import { generateInvoiceNumber } from '@/lib/invoice-server-utils'
import { after } from 'next/server'

const memberSchema = z.object({
    name: z.string().min(2, "Name must be at least 2 characters"),
    phone: z.string().regex(/^\d{10}$/, "Phone number must be exactly 10 digits"),
    email: z.string().email().optional().or(z.literal('')),
    dateOfBirth: z.string()
        .refine(val => !isNaN(Date.parse(val)), { message: "Invalid date format" })
        .transform(str => new Date(str)),
    pincode: z.string().optional(),
    state: z.string().optional(),
    city: z.string().optional(),
    emergencyName: z.string().optional(),
    emergencyPhone: z.string().optional(),
    emergencyRelation: z.string().optional(),
    planId: z.string().optional().or(z.literal('none')),
    paymentMethod: z.enum(["CASH", "UPI", "CARD", "OTHER"]).optional(),
    customPrice: z.number().nonnegative().optional(),
    discount: z.number().nonnegative().optional().default(0),
    amountPaid: z.number().nonnegative().optional(),
})

export const createMember = withAuth(async (context, data: z.input<typeof memberSchema>) => {
    const parsed = memberSchema.safeParse(data)
    if (!parsed.success) {
        return { error: parsed.error.issues[0]?.message || 'Validation failed' }
    }

    const validatedData = parsed.data
    const gymId = context.gym.id
    const slug = context.gym.slug

    try {
        const existingMember = await prisma.member.findFirst({
            where: { phone: validatedData.phone, gymId }
        })
        if (existingMember) return { error: 'Member with this phone number already exists in your gym.' }

        let finalMemberId: string = ""
        let finalInvoiceId: string | undefined = undefined

        await prisma.$transaction(async (tx) => {
            // Capitalize first letter of every word, including after hyphens and apostrophes
            const formattedName = validatedData.name
                .split(' ')
                .map(word =>
                    word.replace(/([^-']+)/g, (segment) =>
                        segment.charAt(0).toUpperCase() + segment.slice(1).toLowerCase()
                    )
                )
                .join(' ')

            // 1. Create the Member
            const member = await tx.member.create({
                data: {
                    name: formattedName,
                    phone: validatedData.phone,
                    email: validatedData.email || null,
                    dateOfBirth: validatedData.dateOfBirth,
                    gymId,
                    status: 'ACTIVE',
                    pincode: validatedData.pincode,
                    state: validatedData.state,
                    city: validatedData.city,
                    emergencyName: validatedData.emergencyName || '',
                    emergencyPhone: validatedData.emergencyPhone || '',
                    emergencyRelation: validatedData.emergencyRelation || '',
                }
            })
            finalMemberId = member.id

            // 2. If a Plan is Selected, Create Subscription and Invoice
            if (validatedData.planId && validatedData.planId !== 'none') {
                const plan = await tx.membershipPlan.findUnique({
                    where: { id: validatedData.planId }
                })

                if (!plan) throw new Error("Selected plan not found")

                const startDate = new Date()
                const endDate = addDays(startDate, plan.duration)
                const paymentMethod = (validatedData.paymentMethod || 'CASH') as PaymentStatus

                const planPrice = (validatedData.customPrice !== undefined && validatedData.customPrice > 0) ? validatedData.customPrice : Number(plan.price)
                const discount = validatedData.discount || 0
                const total = Math.max(0, planPrice - discount)
                const amountPaid = validatedData.amountPaid ?? total
                const balanceDue = Math.max(0, total - amountPaid)

                let paymentStatus: PaymentStatus = 'PAID'
                if (balanceDue > 0 && amountPaid > 0) {
                    paymentStatus = 'PARTIAL'
                } else if (amountPaid === 0 && total > 0) {
                    paymentStatus = 'PENDING'
                }

                // Create the physical subscription linkage
                const subscription = await tx.memberSubscription.create({
                    data: {
                        memberId: member.id,
                        planId: plan.id,
                        gymId,
                        startDate,
                        endDate,
                        price: plan.price,
                        status: 'ACTIVE' as SubscriptionStatus,
                        paymentStatus: paymentStatus
                    }
                })

                // Generate Invoice
                const invoiceNumber = await generateInvoiceNumber(gymId, tx)
                const shareToken = crypto.randomBytes(32).toString('hex')
                const expiryDays = context.gym.invoiceLinkExpiryDays ?? 30
                const shareTokenExpiresAt = expiryDays > 0
                    ? new Date(Date.now() + expiryDays * 24 * 60 * 60 * 1000)
                    : null

                const invoice = await tx.invoice.create({
                    data: {
                        invoiceNumber,
                        gymId,
                        memberId: member.id,
                        subscriptionId: subscription.id,
                        subtotal: planPrice,
                        taxAmount: 0,
                        taxPercentage: 0,
                        discount: discount,
                        total: total,
                        amountPaid: amountPaid,
                        balanceDue: balanceDue,
                        paymentStatus: paymentStatus,
                        paymentMethod: (validatedData.paymentMethod || 'CASH') as any,
                        issueDate: new Date(),
                        dueDate: new Date(),
                        type: 'MEMBERSHIP',
                        shareToken: shareToken,
                        shareTokenExpiresAt: shareTokenExpiresAt,
                        items: {
                            create: [{
                                description: `${plan.name} Membership (${plan.duration} Months)`,
                                amount: planPrice,
                                quantity: 1,
                                unitPrice: planPrice,
                                gymId: gymId,
                            }]
                        }
                    }
                })

                finalInvoiceId = invoice.id
            }
        })

        revalidatePath(`/${slug}/members`)
        revalidatePath(`/${slug}/invoices`)
        revalidatePath(`/${slug}/dashboard`)

        // 4. Audit Log
        const headerList = await headers()
        const ipHeader = headerList.get('x-forwarded-for')
        const ip = ipHeader ? ipHeader.split(',')[0].trim() : '127.0.0.1'

        await recordAuditLog({
            gymId,
            actorId: context.userId,
            action: 'CREATE_MEMBER',
            entityType: 'MEMBER',
            entityId: finalMemberId,
            ipAddress: ip,
            payload: { name: validatedData.name, planId: validatedData.planId }
        }).catch(err => console.error('recordAuditLog CREATE_MEMBER', err))

        // 5. Send Welcome Email ΓÇö now only sent if an email is provided
        after(async () => {
            if (validatedData.email && validatedData.email.length > 0) {
                try {
                    const resendKey = process.env.RESEND_API_KEY
                    if (!resendKey) {
                        console.error('[WelcomeEmail] RESEND_API_KEY not set ΓÇö skipping email')
                        return
                    }

                    const resend = new Resend(resendKey)
                    const gym = context.gym

                    const latestSub = await prisma.memberSubscription.findFirst({
                        where: { memberId: finalMemberId, gymId },
                        include: { plan: true },
                        orderBy: { createdAt: 'desc' }
                    })

                    const { templates, getWhatsAppLink } = await import('@/lib/whatsapp')
                    const { getBaseUrl } = await import('@/lib/utils')

                    let publicInvoiceUrl: string | undefined = undefined
                    if (finalInvoiceId) {
                        const inv = await prisma.invoice.findUnique({
                            where: { id: finalInvoiceId },
                            select: { shareToken: true, gym: { select: { slug: true } } }
                        })
                        if (inv?.shareToken) {
                            publicInvoiceUrl = `${getBaseUrl()}/${inv.gym.slug}/invoice/${inv.shareToken}`
                        }
                    }

                    const invoiceUrl = publicInvoiceUrl

                    const { error } = await resend.emails.send({
                        from: `${gym.name} <hello@mail.emitra.dev>`,
                        to: validatedData.email,
                        subject: `Welcome to ${gym.name}, ${validatedData.name}!`,
                        react: React.createElement(WelcomeEmail, {
                            gymName: gym.name,
                            gymLogo: gym.logoUrl || gym.logo,
                            memberName: validatedData.name,
                            planName: latestSub?.plan.name || 'Pay-as-you-go',
                            expiryDate: latestSub?.endDate ? format(latestSub.endDate, 'PPP') : 'Contact Gym',
                            gymAddress: gym.address,
                            gymContact: gym.phone,
                            invoiceUrl: invoiceUrl,
                            termsAndConditions: gym.termsAndConditions,
                            gymRules: gym.gymRules
                        }) as React.ReactElement
                    })

                    if (error) console.error('[WelcomeEmail] Resend error:', JSON.stringify(error))
                    else console.log('[WelcomeEmail] Sent successfully to', validatedData.email)
                } catch (err) {
                    console.error('[WelcomeEmail] Logic error:', err)
                }
            }
        })

        const { templates, getWhatsAppLink } = await import('@/lib/whatsapp')

        let publicInvoiceUrl: string | undefined = undefined

        if (finalInvoiceId) {
            const inv = await prisma.invoice.findUnique({
                where: { id: finalInvoiceId },
                select: { shareToken: true, gym: { select: { slug: true } } }
            })
            if (inv?.shareToken) {
                const { getBaseUrl } = await import('@/lib/utils')
                publicInvoiceUrl = `${getBaseUrl()}/${inv.gym.slug}/invoice/${inv.shareToken}`
            }
        }

        // @ts-ignore
        const templateOverride = context.gym?.waWelcomeMsg || undefined;
        const welcomeMessage = templates.welcomeMessage(validatedData.name, context.gym.name, publicInvoiceUrl, templateOverride)
        const whatsappUrl = getWhatsAppLink(validatedData.phone, welcomeMessage)

        return { success: true, id: finalMemberId, invoiceId: finalInvoiceId, whatsappUrl }
    } catch (error: any) {
        console.error('Error creating member:', error)
        if (error.code === 'P2002') {
            const target = error.meta?.target
            if (Array.isArray(target)) {
                if (target.includes('email')) {
                    return { error: 'Member with this email already exists.' }
                }
                if (target.includes('phone')) {
                    return { error: 'Member with this phone number already exists.' }
                }
            }
            return { error: 'Member with the same unique field already exists.' }
        }
        return { error: 'Failed to create member.' }
    }
})

export const searchMembers = withAuth(async (_context, formData: FormData) => {
    const query = formData.get('q') as string
    const params = new URLSearchParams()

    if (query && query.trim()) {
        params.set('q', query.trim())
    }

    const slug = _context.gym.slug
    redirect(`/${slug}/members?${params.toString()}`)
})

export const filterByStatus = withAuth(async (_context, status: string) => {
    const params = new URLSearchParams()

    if (status && status !== 'ALL') {
        params.set('status', status)
    }

    const slug = _context.gym.slug
    redirect(`/${slug}/members?${params.toString()}`)
})

/**
 * Normalize phone: strip +91, leading 0, spaces, dashes, parens ΓåÆ 10-digit string.
 * Returns null if the result isn't a valid 10-digit number.
 */
function normalizePhone(raw: string): string | null {
    // Remove all non-digit characters
    let digits = raw.replace(/[^\d]/g, '')
    // Strip country code: 91XXXXXXXXXX ΓåÆ XXXXXXXXXX
    if (digits.length === 12 && digits.startsWith('91')) {
        digits = digits.slice(2)
    }
    // Strip leading 0: 0XXXXXXXXXX ΓåÆ XXXXXXXXXX
    if (digits.length === 11 && digits.startsWith('0')) {
        digits = digits.slice(1)
    }
    // Must be exactly 10 digits
    return digits.length === 10 ? digits : null
}

export const importMembers = withAuth(async (context, data: any[]) => {
    const gymId = context.gym.id
    const slug = context.gym.slug
    let imported = 0
    let skippedDuplicate = 0
    let skippedPlanNotFound = 0
    let skippedInvalidData = 0
    const failedRows: { row: any; reason: string }[] = []

    try {
        // 1. Get existing phones to skip duplicates (normalized)
        const existingMembers = await prisma.member.findMany({
            where: { gymId },
            select: { phone: true }
        })
        const existingPhones = new Set(existingMembers.map(m => m.phone))

        // 2. Get existing plans to map by name (case-insensitive)
        const existingPlans = await prisma.membershipPlan.findMany({
            where: { gymId, isActive: true }
        })
        const planMap = new Map<string, any>(existingPlans.map(p => [p.name.trim().toLowerCase(), p]))

        // 2b. Auto-create missing plans (Pre-pass)
        const uniquePlanNames = new Set<string>()
        for (const row of data) {
            const rowPlanName = String(row.planname || "").trim()
            if (rowPlanName) {
                uniquePlanNames.add(rowPlanName)
            }
        }

        for (const originalPlanName of uniquePlanNames) {
            const lowerPlanName = originalPlanName.toLowerCase()
            if (!planMap.has(lowerPlanName)) {
                try {
                    const newPlan = await prisma.membershipPlan.create({
                        data: {
                            name: originalPlanName,
                            duration: 30, // Default to 30 days
                            price: 0,    // Default to 0 price
                            features: [],
                            isActive: true,
                            gymId,
                        }
                    })
                    planMap.set(lowerPlanName, newPlan)
                } catch (createErr) {
                    console.error(`Failed to auto-create plan: ${originalPlanName}`, createErr)
                }
            }
        }

        // 3. Process rows in batches to avoid timeout
        const BATCH_SIZE = 25;
        for (let i = 0; i < data.length; i += BATCH_SIZE) {
            const batch = data.slice(i, i + BATCH_SIZE);

            await Promise.all(batch.map(async (row) => {
                const rawPhone = String(row.phone || "").trim()
                const name = String(row.name || "").trim()

                // Validate name
                if (!name) {
                    skippedInvalidData++
                    failedRows.push({ row, reason: 'Missing name' })
                    return
                }

                // Normalize & validate phone
                const phone = normalizePhone(rawPhone)
                if (!phone) {
                    skippedInvalidData++
                    failedRows.push({ row, reason: `Invalid phone: "${rawPhone}" (must be 10 digits)` })
                    return
                }

                // Duplicate check (against DB + already-imported)
                if (existingPhones.has(phone)) {
                    skippedDuplicate++
                    failedRows.push({ row, reason: `Duplicate phone: ${phone}` })
                    return
                }
                
                // Add to existing phones immediately before DB syncs to prevent batch parallel duplicates
                existingPhones.add(phone)

                // Plan matching
                const planName = String(row.planname || "").trim().toLowerCase()
                const plan = planName ? planMap.get(planName) : undefined

                if (planName && !plan) {
                    skippedPlanNotFound++
                    failedRows.push({ row, reason: `Plan not found: "${row.planname}"` })
                    existingPhones.delete(phone) // remove if failed
                    return
                }

                // Per-row try/catch ΓÇö one bad row doesn't kill the entire import
                try {
                    const member = await prisma.member.create({
                        data: {
                            name,
                            phone,
                            email: row.email ? String(row.email).trim() : null,
                            dateOfBirth: row.dob ? new Date(row.dob) : new Date(1990, 0, 1),
                            joiningDate: row.joindate ? new Date(row.joindate) : new Date(),
                            gymId,
                            status: 'ACTIVE',
                            city: row.city ? String(row.city).trim() : undefined,
                            emergencyName: '',
                            emergencyPhone: '',
                            emergencyRelation: '',
                        }
                    })

                    // Create Subscription if plan exists
                    if (plan) {
                        const startDate = row.joindate ? new Date(row.joindate) : new Date()
                        const expiryDate = row.expirydate ? new Date(row.expirydate) : null

                        if (expiryDate && isValid(new Date(expiryDate))) {
                            await prisma.memberSubscription.create({
                                data: {
                                    memberId: member.id,
                                    planId: plan.id,
                                    gymId,
                                    startDate: new Date(startDate),
                                    endDate: new Date(expiryDate),
                                    price: plan.price,
                                    status: 'ACTIVE',
                                    paymentStatus: 'PAID'
                                }
                            })
                        }
                    }

                    imported++
                } catch (rowError: any) {
                    skippedInvalidData++
                    failedRows.push({ row, reason: `DB error: ${rowError?.message || 'Unknown error'}` })
                    existingPhones.delete(phone)
                }
            }));
        }

        // Audit Log
        const headerList = await headers()
        const ipHeader = headerList.get('x-forwarded-for')
        const ip = ipHeader ? ipHeader.split(',')[0].trim() : '127.0.0.1'

        await recordAuditLog({
            gymId,
            actorId: context.userId,
            action: 'IMPORT_MEMBERS',
            entityType: 'MEMBER',
            entityId: 'batch',
            ipAddress: ip,
            payload: { imported, skippedDuplicate, skippedPlanNotFound, skippedInvalidData, totalRows: data.length }
        }).catch(err => console.error('recordAuditLog IMPORT_MEMBERS', err))

        revalidatePath(`/${slug}/members`)
        revalidatePath(`/${slug}/dashboard`)

        return { imported, skippedDuplicate, skippedPlanNotFound, skippedInvalidData, failedRows }
    } catch (error: any) {
        console.error('Import error:', error)
        return { error: 'Failed to import members: ' + (error?.message || 'Unknown error'), imported, skippedDuplicate, skippedPlanNotFound, skippedInvalidData, failedRows }
    }
})

"use client"

import { useState } from "react"
import { useRouter, useParams } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { toast } from "sonner"
import { ChevronLeft, Upload, Loader2, Check, AlertCircle } from "lucide-react"
import Link from "next/link"
import { importProducts } from "../actions"
import Papa from "papaparse"
import * as XLSX from "xlsx"

export default function ProductImportPage() {
    const router = useRouter()
    const { slug } = useParams() as { slug: string }
    const [file, setFile] = useState<File | null>(null)
    const [preview, setPreview] = useState<any[]>([])
    const [isParsing, setIsParsing] = useState(false)
    const [isImporting, setIsImporting] = useState(false)
    const [result, setResult] = useState<{
        imported: number,
        skippedDuplicate: number,
        skippedInvalidData: number
    } | null>(null)

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0]
        if (!selectedFile) return

        const isCSV = selectedFile.name.endsWith('.csv')
        const isExcel = selectedFile.name.endsWith('.xlsx') || selectedFile.name.endsWith('.xls')

        if (!isCSV && !isExcel) {
            toast.error("Please upload a CSV or Excel file (.csv, .xlsx, .xls)")
            return
        }

        setFile(selectedFile)
        setPreview([])
        setIsParsing(true)
        setResult(null)

        try {
            if (isCSV) {
                Papa.parse(selectedFile, {
                    header: true,
                    skipEmptyLines: true,
                    transformHeader: (header) => header.trim().toLowerCase(),
                    complete: function (results) {
                        processParsedData(results.data, results.meta.fields || [])
                    },
                    error: function (error: any) {
                        toast.error("Failed to parse CSV: " + error.message)
                        setIsParsing(false)
                    }
                })
            } else {
                const reader = new FileReader()
                reader.onload = (evt) => {
                    const bstr = evt.target?.result
                    const wb = XLSX.read(bstr, { type: 'binary' })
                    const wsname = wb.SheetNames[0]
                    const ws = wb.Sheets[wsname]
                    const data = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[]

                    if (data.length === 0) {
                        toast.error("Excel file is empty")
                        setIsParsing(false)
                        return
                    }

                    const rawHeaders = data[0] as string[]
                    const headers = rawHeaders.map(h => String(h || "").trim().toLowerCase())
                    const rows = data.slice(1)
                        .filter((row: any[]) => row && row.length > 0 && row.some(cell => cell !== undefined && cell !== null && String(cell).trim() !== ""))
                        .map((row: any[]) => {
                            const obj: any = {}
                            headers.forEach((header, index) => {
                                obj[header] = row[index]
                            })
                            return obj
                        })

                    processParsedData(rows, headers)
                }
                reader.onerror = () => {
                    toast.error("Failed to read Excel file")
                    setIsParsing(false)
                }
                reader.readAsBinaryString(selectedFile)
            }
        } catch (err) {
            toast.error("Parsing failed")
            setIsParsing(false)
        }
    }

    const processParsedData = (data: any[], headers: string[]) => {
        const REQUIRED_HEADERS = ['name', 'category', 'price', 'stock']
        const missingHeaders = REQUIRED_HEADERS.filter(h => !headers.includes(h))

        if (missingHeaders.length > 0) {
            toast.error(`Missing required headers: ${missingHeaders.join(', ')}`)
            setPreview([])
            setIsParsing(false)
            return
        }

        if (data.length > 1000) {
            toast.error("Maximum 1000 rows allowed")
            setPreview([])
        } else {
            setPreview(data)
        }
        setIsParsing(false)
    }

    const handleImport = async () => {
        if (!preview.length) return

        setIsImporting(true)
        try {
            const res = await importProducts(preview)
            if (res.error) {
                toast.error(res.error)
            } else {
                setResult({
                    imported: res.imported || 0,
                    skippedDuplicate: res.skippedDuplicate || 0,
                    skippedInvalidData: res.skippedInvalidData || 0
                })
                toast.success("Import completed")
            }
        } catch (error) {
            toast.error("Import failed")
        } finally {
            setIsImporting(false)
        }
    }

    return (
        <div className="container mx-auto p-4 md:p-8 max-w-4xl">
            <div className="flex items-center gap-4 mb-8">
                <Link href={`/${slug}/products`}>
                    <Button variant="ghost" size="icon">
                        <ChevronLeft className="h-4 w-4" />
                    </Button>
                </Link>
                <h1 className="text-3xl font-bold">Import Products</h1>
            </div>

            <Card className="mb-8 border-amber-200 bg-amber-50/30">
                <CardHeader>
                    <div className="flex items-center gap-2 text-amber-800">
                        <AlertCircle className="h-5 w-5" />
                        <CardTitle className="text-lg">IMPORTANT: CSV/Excel Format Requirement</CardTitle>
                    </div>
                </CardHeader>
                <CardContent className="text-amber-900">
                    <p className="mb-2">Your Excel/CSV file <strong>MUST</strong> have these exact column headers:</p>
                    <div className="flex flex-wrap gap-2 text-xs font-mono">
                        {['name', 'category', 'price', 'stock'].map(col => (
                            <span key={col} className="bg-white border border-amber-200 px-2 py-1 rounded">
                                {col}
                            </span>
                        ))}
                        <span className="bg-white border border-slate-200 px-2 py-1 rounded text-slate-500">
                            purchaseprice (optional)
                        </span>
                        <span className="bg-white border border-slate-200 px-2 py-1 rounded text-slate-500">
                            lowstockalert (optional)
                        </span>
                    </div>
                    <p className="mt-4 text-sm font-medium">Note: Category should be one of "PROTEIN", "SUPPLEMENT", "MERCHANDISE", or "OTHER" (or leave blank for OTHER).</p>
                </CardContent>
            </Card>

            <Card className="mb-8">
                <CardHeader>
                    <CardTitle>Step 1: Upload File</CardTitle>
                    <CardDescription>
                        Select your products list CSV or Excel file (max 1000 rows).
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <div className="grid w-full items-center gap-4">
                        <div className="flex flex-col space-y-1.5">
                            <Label htmlFor="product-file">Choose CSV or Excel File</Label>
                            <Input id="product-file" type="file" accept=".csv, .xlsx, .xls" onChange={handleFileChange} disabled={isImporting} />
                        </div>
                    </div>
                </CardContent>
            </Card>

            {preview.length > 0 && !result && (
                <Card className="mb-8">
                    <CardHeader>
                        <CardTitle>Step 2: Preview & Confirm</CardTitle>
                        <CardDescription>
                            Showing first 5 rows of {preview.length} products found.
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <div className="overflow-x-auto border rounded-md mb-6">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-slate-50 border-b">
                                    <tr>
                                        <th className="px-4 py-2">Name</th>
                                        <th className="px-4 py-2">Category</th>
                                        <th className="px-4 py-2">Price</th>
                                        <th className="px-4 py-2">Stock</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {preview.slice(0, 5).map((row, i) => (
                                        <tr key={i} className="border-b last:border-0 font-medium">
                                            <td className="px-4 py-2">{row.name}</td>
                                            <td className="px-4 py-2">{row.category || "OTHER"}</td>
                                            <td className="px-4 py-2">Γé╣{row.price}</td>
                                            <td className="px-4 py-2">{row.stock}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <Button onClick={handleImport} disabled={isImporting} className="w-full h-12 text-lg">
                            {isImporting ? (
                                <>
                                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                                    Importing {preview.length} products...
                                </>
                            ) : (
                                <>
                                    <Check className="mr-2 h-5 w-5" />
                                    Confirm Import
                                </>
                            )}
                        </Button>
                    </CardContent>
                </Card>
            )}

            {result && (
                <Card className="border-blue-200 bg-blue-50/30">
                    <CardHeader>
                        <CardTitle className="text-blue-900 flex items-center">
                            <Check className="mr-2 h-6 w-6 text-green-600" />
                            Import Results
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="space-y-2 text-sm text-blue-900">
                            <p><strong>{result.imported}</strong> products successfully imported.</p>
                            {result.skippedDuplicate > 0 && <p className="text-amber-700"><strong>{result.skippedDuplicate}</strong> skipped (duplicate name).</p>}
                            {result.skippedInvalidData > 0 && <p className="text-red-600"><strong>{result.skippedInvalidData}</strong> skipped (invalid data).</p>}
                        </div>
                        <Button className="mt-6" variant="outline" onClick={() => {
                            setResult(null);
                            setPreview([]);
                            setFile(null);
                            const input = document.getElementById('product-file') as HTMLInputElement;
                            if (input) input.value = '';
                        }}>Upload Another File</Button>
                    </CardContent>
                </Card>
            )}
        </div>
    )
}

"use client"

import { useState, useEffect, useRef } from "react"
import { CheckCircle2, Loader2, Phone, Zap, ArrowRight, RotateCcw, Clock, Delete } from "lucide-react"
import { useParams } from "next/navigation"
import { motion, AnimatePresence } from "framer-motion"

type CheckInState = "idle" | "loading" | "success" | "error"

const STORAGE_KEY_PREFIX = "gm_checkin_phone_"

export default function CheckInPage() {
    const params = useParams()
    const slug = Array.isArray(params.slug) ? params.slug[0] : params.slug || ""

    const [phone, setPhone] = useState("")
    const [savedPhone, setSavedPhone] = useState<string | null>(null)
    const [gymName, setGymName] = useState("")
    const [state, setState] = useState<CheckInState>("idle")
    const [message, setMessage] = useState("")
    const [memberName, setMemberName] = useState("")
    const [isReturningMember, setIsReturningMember] = useState(false)
    const [time, setTime] = useState(new Date())
    const inputRef = useRef<HTMLInputElement>(null)
    const storageKey = `${STORAGE_KEY_PREFIX}${slug}`

    // Clock effect
    useEffect(() => {
        const timer = setInterval(() => setTime(new Date()), 1000)
        return () => clearInterval(timer)
    }, [])

    useEffect(() => {
        // Load gym info
        fetch(`/api/public/${slug}/checkin`)
            .then(r => r.json())
            .then(data => {
                if (data.gymName) setGymName(data.gymName)
            })
            .catch(() => { })

        try {
            const remembered = localStorage.getItem(storageKey)
            if (remembered) {
                setSavedPhone(remembered)
                setPhone(remembered)
                setIsReturningMember(true)
            }
        } catch (e) {
            console.error("localStorage access failed:", e)
        }
    }, [slug, storageKey])

    const handleCheckIn = async (phoneNum: string) => {
        if (phoneNum.length < 10) return
        setState("loading")
        setMessage("")

        try {
            const res = await fetch(`/api/public/${slug}/checkin`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ phone: phoneNum.trim() }),
            })
            const data = await res.json()

            if (!res.ok) {
                setState("error")
                setMessage(data.error || "Something went wrong.")
                setTimeout(() => {
                    setState("idle")
                    setPhone("")
                }, 3000)
                return
            }

            try {
                localStorage.setItem(storageKey, phoneNum.trim())
            } catch (e) {
                console.error("localStorage access failed:", e)
            }
            setSavedPhone(phoneNum.trim())
            setIsReturningMember(true)
            setMemberName(data.memberName || "")
            setState("success")

            // Clear phone input for next time
            setPhone("")

            setTimeout(() => {
                setState("idle")
                setMessage("")
            }, 5000)
        } catch {
            setState("error")
            setMessage("Network error.")
            setTimeout(() => setState("idle"), 3000)
        }
    }

    const appendDigit = (digit: string) => {
        if (phone.length < 10) setPhone(prev => prev + digit)
    }

    const backspace = () => {
        setPhone(prev => prev.slice(0, -1))
    }

    const KeypadButton = ({ value, onClick, className = "" }: { value: string | React.ReactNode, onClick: () => void, className?: string }) => (
        <button
            onClick={onClick}
            className={`h-20 w-20 rounded-full flex items-center justify-center text-2xl font-bold transition-all active:scale-95 active:bg-white/20 select-none ${className}`}
            style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)" }}
        >
            {value}
        </button>
    )

    return (
        <div className="min-h-screen bg-[#050510] text-white flex flex-col items-center justify-between p-6 md:p-12 overflow-hidden relative">
            {/* Background elements */}
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-sky-500/10 blur-[120px] rounded-full" />
            <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-500/10 blur-[120px] rounded-full" />

            {/* Top Bar: Time and Gym Name */}
            <header className="w-full flex items-center justify-between relative z-20">
                <div className="flex flex-col">
                    <h1 className="text-2xl md:text-3xl font-black tracking-tighter uppercase">{gymName || "GymMitra"}</h1>
                    <div className="flex items-center gap-2 text-sky-400 font-bold text-xs tracking-widest uppercase mt-1">
                        <span className="h-1.5 w-1.5 rounded-full bg-sky-400 animate-pulse" />
                        Kiosk Mode Active
                    </div>
                </div>
                <div className="text-right">
                    <div className="text-3xl md:text-5xl font-black tracking-tighter flex items-center justify-end gap-3">
                        <Clock className="h-6 w-6 md:h-8 md:w-8 text-slate-500" />
                        {time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </div>
                    <div className="text-slate-500 text-sm font-bold uppercase tracking-widest mt-1">
                        {time.toLocaleDateString([], { weekday: 'long', day: 'numeric', month: 'short' })}
                    </div>
                </div>
            </header>

            {/* Main Center Area */}
            <main className="flex-1 w-full max-w-7xl flex flex-col md:flex-row items-center justify-center gap-12 md:gap-24 relative z-10">

                <AnimatePresence mode="wait">
                    {state === "success" ? (
                        <motion.div
                            key="success"
                            initial={{ opacity: 0, scale: 0.9, y: 20 }}
                            animate={{ opacity: 1, scale: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 1.1 }}
                            className="flex flex-col items-center text-center space-y-8"
                        >
                            <div className="relative">
                                <div className="h-48 w-48 md:h-64 md:w-64 rounded-full bg-emerald-500/20 border-4 border-emerald-500/50 flex items-center justify-center shadow-[0_0_80px_rgba(16,185,129,0.3)]">
                                    <CheckCircle2 className="h-24 w-24 md:h-32 md:w-32 text-emerald-400" />
                                </div>
                                <motion.div
                                    initial={{ scale: 0 }}
                                    animate={{ scale: 1 }}
                                    transition={{ delay: 0.3, type: "spring" }}
                                    className="absolute -bottom-4 left-1/2 -translate-x-1/2 bg-white text-emerald-600 font-black px-6 py-2 rounded-full shadow-xl"
                                >
                                    SUCCESS
                                </motion.div>
                            </div>

                            <div className="space-y-2">
                                <h2 className="text-4xl md:text-6xl font-black text-white">
                                    {memberName ? `Welcome, ${memberName.split(' ')[0]}!` : "Welcome In!"}
                                </h2>
                                <p className="text-emerald-400 md:text-2xl font-bold tracking-tight">Consistency is the key to success. ≡ƒÆ¬</p>
                            </div>

                            <div className="w-full max-w-xs h-1.5 bg-white/10 rounded-full overflow-hidden mt-8">
                                <motion.div
                                    initial={{ width: "100%" }}
                                    animate={{ width: "0%" }}
                                    transition={{ duration: 5, ease: "linear" }}
                                    className="h-full bg-emerald-400"
                                />
                            </div>
                            <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Resetting in 5 seconds</p>
                        </motion.div>
                    ) : (
                        <motion.div
                            key="kiosk"
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: 20 }}
                            className="w-full flex flex-col md:flex-row items-center justify-center gap-12 md:gap-24"
                        >
                            {/* Left: Branding & Message */}
                            <div className="hidden md:flex flex-col space-y-6 max-w-md">
                                <div className="h-16 w-16 bg-white/5 rounded-2xl flex items-center justify-center border border-white/10">
                                    <Zap className="h-8 w-8 text-sky-400" />
                                </div>
                                <h2 className="text-6xl font-black leading-none tracking-tighter uppercase font-serif">
                                    Ready to <br />
                                    <span className="text-sky-400">Transform?</span>
                                </h2>
                                <p className="text-xl text-slate-400 font-medium">Enter your 10-digit registered phone number to check in.</p>
                                <div className="flex gap-4">
                                    <div className="bg-white/5 border border-white/10 p-4 rounded-2xl flex-1">
                                        <p className="text-xs text-slate-500 font-bold uppercase mb-1">Status</p>
                                        <div className="flex items-center gap-2">
                                            <div className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse" />
                                            <p className="text-lg font-black uppercase text-emerald-400">Live</p>
                                        </div>
                                    </div>
                                    <div className="bg-white/5 border border-white/10 p-4 rounded-2xl flex-1">
                                        <p className="text-xs text-slate-500 font-bold uppercase mb-1">Secure</p>
                                        <p className="text-lg font-black text-slate-300 uppercase">Encrypted</p>
                                    </div>
                                </div>
                            </div>

                            {/* Right: Phone Input & Keypad */}
                            <div className="w-full max-w-sm space-y-8">
                                <div className="relative group">
                                    <div className="absolute inset-0 bg-sky-500/10 blur-[40px] group-focus-within:bg-sky-500/20 transition-all rounded-full" />
                                    <div className="relative">
                                        <div className="text-center md:hidden mb-6">
                                            <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Enter Member Phone</p>
                                        </div>
                                        <div className="flex items-center justify-center gap-3 bg-white/[0.03] border border-white/10 group-focus-within:border-sky-500/50 p-6 rounded-3xl backdrop-blur-xl shadow-2xl transition-all h-24">
                                            <Phone className="h-6 w-6 text-slate-500" />
                                            <div className="flex-1 text-4xl md:text-5xl font-black tracking-[0.2em] text-center font-mono">
                                                {phone.padEnd(10, "┬╖").split("").map((char, i) => (
                                                    <span key={i} className={char === "┬╖" ? "text-white/10" : "text-white"}>
                                                        {char}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {state === "error" && (
                                    <motion.div
                                        initial={{ opacity: 0, y: -10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        className="bg-rose-500/10 border border-rose-500/20 p-4 rounded-2xl text-center"
                                    >
                                        <p className="text-rose-400 font-bold uppercase text-xs tracking-widest">{message}</p>
                                    </motion.div>
                                )}

                                {/* Numeric Keypad */}
                                <div className="grid grid-cols-3 gap-4 place-items-center">
                                    {["1", "2", "3", "4", "5", "6", "7", "8", "9"].map(num => (
                                        <KeypadButton key={num} value={num} onClick={() => appendDigit(num)} />
                                    ))}
                                    <KeypadButton
                                        value={<RotateCcw className="h-8 w-8 text-slate-500" />}
                                        onClick={() => setPhone("")}
                                        className="bg-white/0 border-none"
                                    />
                                    <KeypadButton value="0" onClick={() => appendDigit("0")} />
                                    <KeypadButton
                                        value={<Delete className="h-8 w-8 text-slate-500" />}
                                        onClick={backspace}
                                        className="bg-white/0 border-none"
                                    />
                                </div>

                                <button
                                    onClick={() => handleCheckIn(phone)}
                                    disabled={phone.length < 10 || state === "loading"}
                                    className="w-full h-20 rounded-3xl font-black text-2xl text-white transition-all duration-300 flex items-center justify-center gap-4 disabled:opacity-20 relative overflow-hidden group shadow-[0_0_24px_rgba(14,165,233,0.2)]"
                                    style={{
                                        background: state === "loading"
                                            ? "rgba(14,165,233,0.3)"
                                            : "linear-gradient(135deg, #0EA5E9 0%, #6366F1 100%)",
                                    }}
                                >
                                    {state === "loading" ? (
                                        <Loader2 className="h-8 w-8 animate-spin" />
                                    ) : (
                                        <>
                                            CHECK IN
                                            <ArrowRight className="h-6 w-6 group-hover:translate-x-2 transition-transform" />
                                        </>
                                    )}
                                </button>

                                {isReturningMember && savedPhone && phone !== savedPhone && (
                                    <button
                                        onClick={() => { setPhone(savedPhone); handleCheckIn(savedPhone); }}
                                        className="w-full text-center text-slate-500 hover:text-white font-bold text-sm uppercase tracking-widest pt-2 transition-colors"
                                    >
                                        Use previous: {savedPhone.slice(0, 3)}...{savedPhone.slice(-4)}
                                    </button>
                                )}
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

            </main>

            {/* Bottom Footer */}
            <footer className="w-full flex items-center justify-between text-slate-700 font-bold text-[10px] md:text-xs uppercase tracking-[0.3em] relative z-20 pt-12">
