    useEffect(() => {
        if (initialData) {
            setData(Array.isArray(initialData) ? initialData : [])
            setLoading(false)
            return;
        }
        fetch('/api/reports?type=revenue')
            .then(res => res.json())
            .then(data => {
                setData(Array.isArray(data) ? data : [])
