function ExpiringMembershipsReport({ initialData, gymName = "this gym" }: { initialData?: ExpiringMembership[], gymName?: string }) {
    const [data, setData] = useState<ExpiringMembership[]>(initialData || [])
    const [loading, setLoading] = useState(!initialData)

    useEffect(() => {
        if (initialData) {
            const processed = (Array.isArray(initialData) ? initialData : []).map(sub => {
                const diff = new Date(sub.endDate).getTime() - new Date().getTime();
                return { ...sub, daysLeft: Math.max(0, Math.ceil(diff / (1000 * 3600 * 24))) };
            });
            setData(processed)
            setLoading(false)
            return;
        }
        fetch('/api/reports?type=expiring')
            .then(res => res.json())
            .then(data => {
                const processed = (Array.isArray(data) ? data : []).map(sub => {
                    const diff = new Date(sub.endDate).getTime() - new Date().getTime();
                    return { ...sub, daysLeft: Math.max(0, Math.ceil(diff / (1000 * 3600 * 24))) };
                });
                setData(processed)
                setLoading(false)
            })
            .catch(err => {
                console.error(err)
                setLoading(false)
            })
    }, [initialData])

    if (loading) return <div className="flex justify-center p-8"><Loader2 className="animate-spin" /></div>

    return (
        <Card>
            <CardHeader>
                <div className="flex items-center justify-between">
                    <div>
                        <CardTitle className="flex items-center gap-2">
                            <AlertTriangle className="h-5 w-5 text-yellow-500" />
                            Expiring Soon
                        </CardTitle>
                        <CardDescription>Memberships ending in the next 7 days.</CardDescription>
                    </div>
                    <a href="/api/reports/download?type=members" download>
                        <Button variant="outline" size="sm">
                            <Download className="mr-2 h-4 w-4" /> Export CSV
                        </Button>
                    </a>
                </div>
            </CardHeader>
            <CardContent>
                {data.length === 0 ? (
                    <div className="text-center py-8 text-muted-foreground">
                        No memberships expiring soon.
                    </div>
                ) : (
                    <div className="space-y-4">
                        {data.map((sub) => (
                            <div key={sub.id} className="flex items-center justify-between border-b pb-4 last:border-0 last:pb-0">
                                <div className="flex items-center gap-4">
                                    <Avatar>
                                        <AvatarImage src={sub.member.photo || undefined} />
                                        <AvatarFallback>
                                            {(sub.member?.name || "?")[0]}
                                        </AvatarFallback>
                                    </Avatar>
                                    <div>
                                        <p className="font-medium">{sub.member.name}</p>
                                        <p className="text-sm text-muted-foreground">{sub.plan.name}</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2">
                                    <div className="text-right">
                                        <div className="font-medium text-sm">
                                            Expires: {format(new Date(sub.endDate), "dd/MM/yyyy")}
                                        </div>
                                        <Badge variant="outline" className="mt-1 border-yellow-500 text-yellow-600 bg-yellow-50">
                                            {sub.daysLeft ?? 0} days left
                                        </Badge>
                                    </div>
                                    <Button
                                        size="icon"
                                        variant="ghost"
                                        className="text-brand-primary hover:text-emerald-700 hover:bg-emerald-50"
                                        onClick={() => {
                                            const link = getWhatsAppLink(
                                                sub.member.phone,
                                                templates.renewalReminder(sub.member.name, sub.daysLeft || 0, gymName)
                                            )
                                            window.open(link, '_blank')
                                        }}
                                    >
                                        <MessageSquare className="h-4 w-4" />
                                    </Button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </CardContent>
        </Card>
    )
}

'use client'

import { useRouter, useSearchParams } from 'next/navigation'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Search } from 'lucide-react'
import { useState, useTransition } from 'react'
import { useOrgSlug } from '@/hooks/use-org-slug'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'

export function MemberSearch() {
    const router = useRouter()
    const searchParams = useSearchParams()
    const slug = useOrgSlug()
    const [query, setQuery] = useState(searchParams.get('q') || '')
    const [isPending, startTransition] = useTransition()

    const handleSearch = (e: React.FormEvent) => {
        e.preventDefault()
        if (!slug) return // guard: no slug ΓåÆ don't navigate

        const params = new URLSearchParams(searchParams.toString())

        if (query.trim()) {
            params.set('q', query.trim())
        } else {
            params.delete('q')
        }

        startTransition(() => {
            router.push(`/${slug}/members?${params.toString()}`)
        })
    }

    return (
        <form onSubmit={handleSearch} className="relative flex-1">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
                placeholder="Search by name, phone, or email..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                className="pl-8 w-full max-w-sm"
                disabled={isPending}
            />
        </form>
    )
}

export function MemberFilters() {
    const router = useRouter()
    const searchParams = useSearchParams()
    const slug = useOrgSlug()
    const [isPending, startTransition] = useTransition()
    const currentStatus = searchParams.get('status') || 'ALL'
    const currentMonth = searchParams.get('dobMonth') || 'ALL'
    const currentDuration = searchParams.get('duration') || 'ALL'

    const handleFilter = (status: string) => {
        if (!slug) return // guard: no slug ΓåÆ don't navigate

        const params = new URLSearchParams(searchParams.toString())
        params.delete('page')

        if (status === 'ALL') {
            params.delete('status')
        } else {
            params.set('status', status)
        }

        startTransition(() => {
            router.push(`/${slug}/members?${params.toString()}`)
        })
    }

    const handleFilterMonth = (month: string) => {
        if (!slug) return

        const params = new URLSearchParams(searchParams.toString())
        params.delete('page')

        if (month === 'ALL') {
            params.delete('dobMonth')
        } else {
            params.set('dobMonth', month)
        }

        startTransition(() => {
            router.push(`/${slug}/members?${params.toString()}`)
        })
    }

    const handleFilterBirthday = () => {
        if (!slug) return

        const params = new URLSearchParams(searchParams.toString())
        params.delete('page')

        if (searchParams.get('birthday') === 'today') {
            params.delete('birthday')
        } else {
            params.set('birthday', 'today')
            // Optionally clear dobMonth if today is selected
            params.delete('dobMonth')
        }

        startTransition(() => {
            router.push(`/${slug}/members?${params.toString()}`)
        })
    }

    const handleFilterDuration = (duration: string) => {
        if (!slug) return

        const params = new URLSearchParams(searchParams.toString())
        params.delete('page')

        if (duration === 'ALL') {
            params.delete('duration')
        } else {
            params.set('duration', duration)
        }

        startTransition(() => {
            router.push(`/${slug}/members?${params.toString()}`)
        })
    }

    return (
        <div className="flex gap-2 items-center flex-wrap">
            <Select value={currentMonth} onValueChange={handleFilterMonth} disabled={isPending}>
                <SelectTrigger className="w-[140px] h-9 bg-white">
                    <SelectValue placeholder="Birthday Month" />
                </SelectTrigger>
                <SelectContent>
                    <SelectItem value="ALL">All Birthdays</SelectItem>
                    <SelectItem value="1">January</SelectItem>
                    <SelectItem value="2">February</SelectItem>
                    <SelectItem value="3">March</SelectItem>
                    <SelectItem value="4">April</SelectItem>
                    <SelectItem value="5">May</SelectItem>
                    <SelectItem value="6">June</SelectItem>
                    <SelectItem value="7">July</SelectItem>
                    <SelectItem value="8">August</SelectItem>
                    <SelectItem value="9">September</SelectItem>
                    <SelectItem value="10">October</SelectItem>
                    <SelectItem value="11">November</SelectItem>
                    <SelectItem value="12">December</SelectItem>
                </SelectContent>
            </Select>

            <Select value={currentDuration} onValueChange={handleFilterDuration} disabled={isPending}>
                <SelectTrigger className="w-[140px] h-9 bg-white">
                    <SelectValue placeholder="Plan Duration" />
                </SelectTrigger>
                <SelectContent>
                    <SelectItem value="ALL">All Durations</SelectItem>
                    <SelectItem value="1">1 Month</SelectItem>
                    <SelectItem value="3">3 Months</SelectItem>
                    <SelectItem value="6">6 Months</SelectItem>
                    <SelectItem value="12">12 Months</SelectItem>
                </SelectContent>
            </Select>

            <div className="flex gap-2">
                <Button
                    variant={searchParams.get('birthday') === 'today' ? 'default' : 'outline'}
                    size="sm"
                    onClick={handleFilterBirthday}
                    disabled={isPending}
                    className={searchParams.get('birthday') === 'today' ? 'bg-pink-600 hover:bg-pink-700 text-white' : ''}
                >
                    ≡ƒÄé Today's Birthday
                </Button>
                <div className="w-[1px] h-6 bg-gray-200 mx-1" />
                <Button
                    variant={currentStatus === 'ALL' && !searchParams.get('birthday') ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => handleFilter('ALL')}
                    disabled={isPending}
                >
                    All
                </Button>
                <Button
                    variant={currentStatus === 'ACTIVE' ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => handleFilter('ACTIVE')}
                    disabled={isPending}
                >
                    Active
                </Button>
                <Button
                    variant={currentStatus === 'INACTIVE' ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => handleFilter('INACTIVE')}
                    disabled={isPending}
                >
                    Inactive
                </Button>
                <Button
                    variant={currentStatus === 'EXPIRED' ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => handleFilter('EXPIRED')}
                    disabled={isPending}
                >
                    Expired
                </Button>
            </div>
        </div>
    )
}

'use client'

import React, { useState, useEffect } from 'react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { toast } from "sonner"
import { Loader2, Plus, Edit2, Trash2 } from "lucide-react"

export function PlanManagement() {
    const [plans, setPlans] = useState<any[]>([])
    const [loading, setLoading] = useState(true)
    const [isFormOpen, setIsFormOpen] = useState(false)
    const [saving, setSaving] = useState(false)
    const [editingId, setEditingId] = useState<string | null>(null)

    const [formData, setFormData] = useState({
        name: '',
        description: '',
        duration: 1,
        price: 0,
    })

    const fetchPlans = async () => {
        try {
            const res = await fetch('/api/memberships/plans')
            if (res.ok) {
                const data = await res.json()
                setPlans(data)
            }
        } catch (err) {
            toast.error("Failed to load plans")
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        fetchPlans()
    }, [])

    const handleSave = async () => {
        if (!formData.name || formData.duration <= 0 || formData.price < 0) {
            toast.error("Please fill in all required fields correctly.")
            return
        }

        setSaving(true)
        try {
            const url = editingId ? `/api/memberships/plans/${editingId}` : '/api/memberships/plans'
            const method = editingId ? 'PUT' : 'POST'

            const res = await fetch(url, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData)
            })

            if (!res.ok) throw new Error("Failed to save plan")

            toast.success(`Plan ${editingId ? 'updated' : 'created'} successfully`)
            setIsFormOpen(false)
            setEditingId(null)
            fetchPlans()
        } catch (err: any) {
            toast.error(err.message)
        } finally {
            setSaving(false)
        }
    }

    const handleDelete = async (id: string) => {
        if (!confirm("Are you sure you want to delete this plan? Active memberships might be affected.")) return

        try {
            const res = await fetch(`/api/memberships/plans/${id}`, { method: 'DELETE' })
            if (!res.ok) throw new Error("Failed to delete plan")

            toast.success("Plan deleted successfully")
            fetchPlans()
        } catch (err: any) {
            toast.error(err.message)
        }
    }

    const openEdit = (plan: any) => {
        setFormData({
            name: plan.name,
            description: plan.description || '',
            duration: plan.duration,
            price: plan.price
        })
        setEditingId(plan.id)
        setIsFormOpen(true)
    }

    const openCreate = () => {
        setFormData({ name: '', description: '', duration: 1, price: 0 })
        setEditingId(null)
        setIsFormOpen(true)
    }

    if (loading) return <div className="flex h-32 items-center justify-center"><Loader2 className="w-6 h-6 animate-spin text-primary" /></div>

    if (isFormOpen) {
        return (
            <Card>
                <CardHeader>
                    <CardTitle>{editingId ? 'Edit Plan' : 'Create New Plan'}</CardTitle>
                    <CardDescription>Configure membership pricing and duration.</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="space-y-2">
                        <Label>Plan Name</Label>
                        <Input value={formData.name} onChange={e => setFormData({ ...formData, name: e.target.value })} placeholder="e.g., Monthly Gold" />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Duration (Months)</Label>
                            <Input type="number" value={formData.duration} onChange={e => setFormData({ ...formData, duration: Number(e.target.value) })} />
                        </div>
                        <div className="space-y-2">
                            <Label>Suggested Price (Γé╣)</Label>
                            <Input type="number" value={formData.price} onChange={e => setFormData({ ...formData, price: Number(e.target.value) })} />
                            <p className="text-[10px] text-muted-foreground">Shown as a reference when adding members. Actual price is set per-member.</p>
                        </div>
                    </div>
                    <div className="space-y-2">
                        <Label>Description</Label>
                        <Textarea value={formData.description} onChange={e => setFormData({ ...formData, description: e.target.value })} placeholder="Plan details..." />
                    </div>
                    <div className="flex justify-end gap-3 pt-4">
                        <Button variant="outline" onClick={() => setIsFormOpen(false)}>Cancel</Button>
                        <Button disabled={saving} onClick={handleSave}>
                            {saving && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            Save Plan
                        </Button>
                    </div>
                </CardContent>
            </Card>
        )
    }

    return (
        <Card>
            <CardHeader className="flex flex-row items-center justify-between">
                <div>
                    <CardTitle>Membership Plans</CardTitle>
                    <CardDescription>Manage your gym's membership offerings.</CardDescription>
                </div>
                <Button onClick={openCreate} size="sm">
                    <Plus className="w-4 h-4 mr-2" /> Add Plan
                </Button>
            </CardHeader>
            <CardContent>
                <div className="space-y-4">
                    {plans.map(plan => (
                        <div key={plan.id} className="flex items-center justify-between p-4 border rounded-lg bg-slate-50/50">
                            <div>
                                <h4 className="font-bold text-slate-900">{plan.name}</h4>
                                <p className="text-sm text-slate-500">{plan.duration} Month{plan.duration !== 1 ? 's' : ''} ┬╖ Suggested Γé╣{plan.price}</p>
                            </div>
                            <div className="flex gap-2">
                                <Button variant="ghost" size="icon" onClick={() => openEdit(plan)}>
                                    <Edit2 className="w-4 h-4 text-slate-500" />
                                </Button>
                                <Button variant="ghost" size="icon" onClick={() => handleDelete(plan.id)}>
                                    <Trash2 className="w-4 h-4 text-rose-500" />
                                </Button>
                            </div>
                        </div>
                    ))}
                    {plans.length === 0 && (
                        <div className="text-center p-8 border border-dashed rounded-lg">
                            <p className="text-slate-500">No membership plans found.</p>
                            <Button variant="link" onClick={openCreate} className="mt-2">Create your first plan</Button>
                        </div>
                    )}
                </div>
            </CardContent>
        </Card>
    )
}
